import React from 'react';
import ReactDOM from 'react-dom/client';
import { useNavigate } from 'react-router-dom';

import './home.css'
function Home(){
      const navigate = useNavigate();

    const ViewResult=()=>{
        navigate('/ViewResult1');


    }
    const  Teacherlogin =()=>{
        navigate('/Teacherlogin1')
    }
    return(
        <>
        <div className='main'>
            <div  className='nav-bar'>
                <div className='logo'>
                    <img src="logo.jpeg" width="50px" height="50px"/></div>    
                    <div className="nav-items">
                        <div className="option1" >View Results</div><div className="option2"> results</div></div>        </div>
                        <div  className='body'>
                            <div >
                                <img src="main.png" width="928px" height="218px" className='main-img'/>
                                

                            </div>
                            <span className='main-content'> 
                                Acme High is dedicated to providing a supportive and challenging educational environment. Our commitment to excellence is reflected in our students' achievements and our faculty's dedication. Explore our results and see how we're shaping future leaders.
                            </span>
                            <div className='main-button'>
                            < button className='button1 ' onClick={ViewResult}> view results</button>
                                                        <button  className='button2' onClick={Teacherlogin}> Teacher login</button>

                            </div>
                            <div className='contact'>
                                <div className='contact1'>
                                    Contact Us
                                </div>   <div className='contact1'>
                                    Privacy policy
                                </div>   <div className='contact1'>
Term and Services                                </div>
                            </div>
                            <span className='footer'>
                                @2025 Acme High. All rights reserved.
                            </span>
                        </div>


        </div>
        </>
    );
}
export default Home;
